# Manual mutants (mutmut-style, one targeted change each) for the security-critical lines. (id, target, old, new)
M=[
# --- mp-deploy.v31: FREEZE / config ---
("D01","mp-deploy.v31",'[ "$MODE" = enforce ] && deny FROZEN "current=${CURRENT:-none}" 78','[ "$MODE" = enforce ] && alog FROZEN-skipped'),
("D02","mp-deploy.v31",'if [ "$FREEZE" = 1 ] && [ "$SHA" != "$CURRENT" ]; then','if [ "$FREEZE" = 2 ] && [ "$SHA" != "$CURRENT" ]; then'),
("D03","mp-deploy.v31",'[ "$MODE" = report ] && [ "$FREEZE" != 1 ] && { alog "conf_invalid report_requires_freeze"; BADCONF=1; }',':'),
("D04","mp-deploy.v31",'[ "$BADCONF" = 1 ] && { MODE=enforce; FREEZE=1;','[ "$BADCONF" = 1 ] && { MODE=enforce; FREEZE=0;'),
("D05","mp-deploy.v31",'      *) BADCONF=1;;\n    esac\n  done < "$AUTHZ_CONF"','      *) ;;\n    esac\n  done < "$AUTHZ_CONF"'),
("D06","mp-deploy.v31",'if safe_file "$AUTHZ_CONF" 600 && safe_ancestors "$AUTHZ_CONF"; then','if [ -f "$AUTHZ_CONF" ]; then'),
("D07","mp-deploy.v31",'FREEZE=1; fi\n','fi\n'),   # freeze latch ignored
("D08","mp-deploy.v31",'deny FROZEN "after_eval eval_fail=$EVAL_FAIL','alog FROZEN "after_eval eval_fail=$EVAL_FAIL'),
("D09","mp-deploy.v31",'[ "$FREEZE" = 1 ] && finish FROZEN "same sha not healthy-deployed; no rebuild under freeze" 78',':'),
# --- authz / consume / approved ---
("D10","mp-deploy.v31",'    authz_verify consume\n','    AZ_OK=1\n'),
("D11","mp-deploy.v31",'step_fail AUTHZ_REFUSED "approved: $TW" 77','alog "approved ignored $TW"'),
("D12","mp-deploy.v31",'typeof r.run_id==="string"&&','' ),
("D13","mp-deploy.v31",'elif [ "$EVAL_ONLY" = 1 ] || [ "$MODE" = enforce ]; then step_fail AUTHZ_REFUSED "verify: $AZ_WHY" 77','elif [ "$EVAL_ONLY" = 1 ]; then step_fail AUTHZ_REFUSED "verify: $AZ_WHY" 77'),
("D14","mp-deploy.v31",'[ "$(stat -c %a "$LEDGER")" = 700 ]','true'),
("D15","mp-deploy.v31",'[ "$(sha256sum "$VERIFIER" | cut -d\' \' -f1)" = "$VSUM" ] || { AZ_WHY="AUTHZ_VERIFIER_HASH"; return; }',':'),
("D16","mp-deploy.v31",'if [ "$MODE" = enforce ] || [ "$EVAL_ONLY" = 1 ]; then\n  if [ "$AZ_OK" = 1 ]; then\n    authz_verify consume','if [ "$EVAL_ONLY" = 1 ]; then\n  if [ "$AZ_OK" = 1 ]; then\n    authz_verify consume'),
# --- main-tip ordering ---
("D20","mp-deploy.v31",'step_fail TIP_REFUSED "main_tip_1: $TW" 79','alog "tip1 ignored"'),
("D21","mp-deploy.v31",'else runuser -u "$BUILD_USER" -- rm -rf "$W"; finish TIP_REFUSED "main_tip_2: $TW" 79; fi','else log ignored; fi'),
("D22","mp-deploy.v31",'  finish TIP_REFUSED "main_tip_3: $TW" 79\n','  log ignored\n'),
("D23","mp-deploy.v31",'  [ "$D" != "$PREV" ] && rm -rf "$D"\n',''),
("D24","mp-deploy.v31",'  runuser -u "$BUILD_USER" -- rm -rf "$W"\n  finish TIP_REFUSED "main_tip_3','  finish TIP_REFUSED "main_tip_3'),
("D25","mp-deploy.v31",'      CONSUME_MARKER="$M"     # consumed','      rm -f "$M"; CONSUME_MARKER="$M"     # consumed'),
("D26","mp-deploy.v31",'echo "$SHA FAIL_HEALTH rollback=$R $(date -Is)" > "$STATE/freeze-latch"',':'),
# --- integrity ---
("D30","mp-deploy.v31",'chk "$VERIFIER" "$VSUM" 644','chk "$VERIFIER" "$VSUM"'),
("D31","mp-deploy.v31",'chk "$GATEDIR/runner-job-guard.mjs" "$GUARDSUM" 644',':'),
("D32","mp-deploy.v31",'chk "$HOOK" "$HOOKSUM" 755','chk "$HOOK" "$HOOKSUM"'),
("D33","mp-deploy.v31",'chk "$NODE" "$NODESUM" 755',':'),
("D34","mp-deploy.v31",'  [ -n "$sum" ] && [ "$(sha256sum "$f" | cut -d\' \' -f1)" = "$sum" ] || INTEG+=" hash:$f"; }','  :; }'),
("D35","mp-deploy.v31",'    [ $(( 0$(stat -c %a "$d") & 022 )) -eq 0 ] || return 1\n',''),
("D36","mp-deploy.v31",'&& INTEG+=" legacy_verifier_present"','&& :'),
("D37","mp-deploy.v31",'[ -n "$WFBLOB" ] && [ "$PIN" = "$WFBLOB" ] || INTEG+=" workflow_pin"',':'),
("D38","mp-deploy.v31",'   && [ "$(grep -c \'\' "$RUNNER_ENV")" = "$(grep -cE \'^(LANG=[A-Za-z0-9_.@-]+|ACTIONS_RUNNER_HOOK_JOB_STARTED=.*)$\' "$RUNNER_ENV")" ] \\\n',''),
("D39","mp-deploy.v31",'   && [ "$(stat -c %G "$RUNNER_ENV")" = "$RUNNER_GROUP" ]',''),
("D40","mp-deploy.v31",'[ "$SLN" = "$EXP_SL" ] || INTEG+=" sudo_effective"',':'),
("D41","mp-deploy.v31",'[ "$(id -nG "$RUNNER_USER" 2>/dev/null)" = "$RUNNER_USER" ] || INTEG+=" sudo_groups"',':'),
("D42","mp-deploy.v31",'[ "$INC" = "@includedir $SUDOERS_DIR" ] || INTEG+=" sudo_includes"',':'),
("D43","mp-deploy.v31",'[ "$RUNNER_LINES" = "$RUNNER_USER ALL=(root) NOPASSWD: /usr/local/sbin/mp-deploy" ] || INTEG+=" sudo_files_runner"',':'),
("D44","mp-deploy.v31","sed -e ':a' -e '/\\\\$/N; s/\\\\\\n/ /; ta' | ",""),
("D45","mp-deploy.v31",'(%?$RUNNER_USER|#$RUID|%#$RGID)','(%?$RUNNER_USER)'),
("D46","mp-deploy.v31","printf '%s\\n' \"$SBODY\" | grep -qE '^ALL[[:space:],=]' && INTEG+=\" sudo_files_all_users\"",":"),
("D47","mp-deploy.v31",'{ [ -n "$SUDOSUM" ] && [ "$(sudoers_digest)" = "$SUDOSUM" ]; } || INTEG+=" sudoers_pin"',':'),
("D48","mp-deploy.v31",'for f in "${SFILES[@]}"; do { safe_file "$f" 440 && safe_ancestors "$f"; } || INTEG+=" unsafe_sudoers:$(basename "$f")"; done',':'),
("D49","mp-deploy.v31",'|| INTEG+=" unsafe_sudoers_dir"','|| :'),
("D50","mp-deploy.v31",'[ "$(stat -c %a "$LOCKDIR")" = 700 ]; } || deny LOCK_UNSAFE','true; } || deny LOCK_UNSAFE'),
("D51","mp-deploy.v31","grep -vE '^[[:space:]]*(#([^0-9]|$)|$)'","grep -vE '^[[:space:]]*(#|$)'"),
# --- runner hook ---
("K01","mp-runner-guard.sh.in",'[ "${GITHUB_WORKFLOW_REF:-}" = "$EXPECTED_WF_REF" ] || fail',': || fail'),
("K02","mp-runner-guard.sh.in",'[ "${GITHUB_EVENT_NAME:-}" = "$EXPECTED_EVENT" ] || fail',': || fail'),
("K03","mp-runner-guard.sh.in",'pinned "$NODE" "$NODE_SHA256" || fail "integrity node"',':'),
("K04","mp-runner-guard.sh.in",'pinned "$GATEDIR/runner-job-guard.mjs" "$GUARD_SHA256" || fail',': || fail'),
("K05","mp-runner-guard.sh.in",'pinned "$GATEDIR/deploy-authz.mjs" "$AUTHZ_SHA256" || fail',': || fail'),
("K06","mp-runner-guard.sh.in",'OUT=$(env -i PATH','OUT=$(env PATH'),
("K07","mp-runner-guard.sh.in",'if [ "$RC" = 0 ] && printf','if printf'),
("K08","mp-runner-guard.sh.in","grep -q '^{\"guard\":\"MP-RUNNER-JOB-GUARD\",\"result\":\"ALLOW\"'","grep -q 'MP-RUNNER-JOB-GUARD'"),
("K09","mp-runner-guard.sh.in",'timeout "$GUARD_TIMEOUT" "$NODE"','"$NODE"'),
("K10","mp-runner-guard.sh.in",'|| fail "integrity guard config"',''),
("K11","mp-runner-guard.sh.in",'[ ! -L "$1" ] && ',''),
("K12","mp-runner-guard.sh.in",'|| fail "integrity gate dir"',''),
# --- installer ---
("I01","install-v31.sh",'[ "$(sha "$K/deploy-gate.mjs")" = $EXP_GATE ]','true'),
("I02","install-v31.sh",'grep -qx \'FREEZE=1\' "$CONF" || { echo "PRECONDITION','true || { echo "PRECONDITION'),
("I03","install-v31.sh",'printf \'MODE=report\\nFREEZE=1\\n','printf \'MODE=enforce\\nFREEZE=0\\n'),
("I04","install-v31.sh",'[ -f "$LEG" ] && rm -f "$LEG"     # NB-E',':     # NB-E'),
("I05","install-v31.sh",'grep -qx \'FREEZE=1\' "$B/authz.conf" || { echo "REFUSE','true || { echo "REFUSE'),
("I06","install-v31.sh",'B="$arg"; (cd "$B" && sha256sum -c --quiet SHA256SUMS) || { echo "BACKUP_CORRUPT"; exit 1; }','B="$arg"'),
("I07","install-v31.sh",'cp -p "$HOOK" "$B/mp-runner-guard.sh"','true'),
("I08","install-v31.sh",'flock -n "$OLDLOCK" sh -c "mv -T \'$CONF.new\' \'$CONF\' && mv -T \'$HOOK.new\' \'$HOOK\' && mv -T \'$SB.new\' \'$SB\'" || { rm -f "$CONF.new" "$HOOK.new" "$SB.new"; echo "LOCK_BUSY"; exit 75; }\n  [ -f "$LEG" ]','sh -c "mv -T \'$CONF.new\' \'$CONF\' && mv -T \'$HOOK.new\' \'$HOOK\' && mv -T \'$SB.new\' \'$SB\'"\n  [ -f "$LEG" ]'),
("I09","install-v31.sh",'grep -q \'@MP-TEST-SHIM@\' "$K/mp-deploy.v31" && ! grep -q \'MP_\' <(grep -v \'@MP-TEST-SHIM@\' "$K/mp-deploy.v31") || { echo "PKG_NOT_PRODUCTION"; exit 1; }',':'),
]
# controls (no-op "mutants"): must SURVIVE, proving the suites are not flaky under parallel load
M+=[("C01","mp-deploy.v31",'KEEP=5\n','KEEP=5 \n'),("C02","mp-runner-guard.sh.in",'GUARD_TIMEOUT=90\n','GUARD_TIMEOUT=90 \n'),("C03","install-v31.sh",'sha(){ sha256sum "$1" | cut -d\' \' -f1; }','sha(){  sha256sum "$1" | cut -d\' \' -f1; }')]
